<?php $c=require 'config/local.php';$p=new PDO('mysql:host='.$c['host'].';dbname='.$c['database'],$c['username'],$c['password']);foreach(['SELECT id,status,total_amount,official_number FROM fin_invoices WHERE id=1','SELECT COALESCE(SUM(amount),0) x FROM fin_payments WHERE status="POSTED"','SELECT COALESCE(SUM(debit),0) x FROM fin_cash_ledger WHERE reference_type="PAYMENT"'] as $q){var_export($p->query($q)->fetch(PDO::FETCH_ASSOC));echo PHP_EOL;}
